defmodule GrowthBook.ConditionJsParityTest do
  use ExUnit.Case, async: true
  alias GrowthBook.Condition

  # Expected values are generated by evaluating each case with the JavaScript SDK
  cases = "test/fixtures/js_parity_cases.json" |> File.read!() |> Jason.decode!()

  describe "Condition.eval_condition/2 matches the JS SDK" do
    for [desc, condition, attributes, expected] <- cases do
      test desc do
        assert unquote(expected) ==
                 Condition.eval_condition(
                   unquote(Macro.escape(attributes)),
                   unquote(Macro.escape(condition))
                 )
      end
    end

    test "float attributes convert like JS numbers" do
      assert Condition.eval_condition(%{"x" => 1.0}, %{"x" => "1"})
      assert Condition.eval_condition(%{"x" => 2}, %{"x" => 2.0})
      assert Condition.eval_condition(%{"x" => 1.0}, %{"x" => %{"$veq" => "1"}})
      refute Condition.eval_condition(%{"x" => 0.0}, %{"x" => true})
    end
  end

  describe "Condition.js_string/1" do
    test "formats floats like JS String(number)" do
      assert "1" == Condition.js_string(1.0)
      assert "1e+21" == Condition.js_string(1.0e21)
      assert "100000000000000000000" == Condition.js_string(1.0e20)
      assert "1e-7" == Condition.js_string(1.0e-7)
      assert "0.000001" == Condition.js_string(1.0e-6)
      assert "0.0001" == Condition.js_string(0.0001)
      assert "-2.5" == Condition.js_string(-2.5)
      assert "123456789.123" == Condition.js_string(123_456_789.123)
      assert "5e-324" == Condition.js_string(5.0e-324)
      assert "1.7976931348623157e+308" == Condition.js_string(1.7976931348623157e308)
    end
  end
end
